parts = {"CloudFront": 0.999, "ALB": 0.9999, "ECS(Fargate)": 0.9999, "Aurora": 0.9999}
total = 1.0
for a in parts.values():
    total *= a
print(f"직렬 합계 가용성 {total*100:.3f}%")   # 99.870%
for slo in (0.995, 0.999, 0.9995):
    print(f"목표 {slo*100:.2f}% → 30일 허용 정지 {30*24*60*(1-slo):.1f}분")
# 목표 99.50% → 30일 허용 정지 216.0분
# 목표 99.90% → 30일 허용 정지 43.2분
# 목표 99.95% → 30일 허용 정지 21.6분
